class Solution {
  public long maximumScore(int[] nums) {
    int n = nums.length;
    long[] suffixMin = new long[n + 1];
    suffixMin[n] = Long.MAX_VALUE;
    for (int i = n - 1; i >= 0; i--) suffixMin[i] = Math.min(suffixMin[i + 1], nums[i]);
    long prefix = 0, best = Long.MIN_VALUE;
    for (int i = 0; i + 1 < n; i++) {
      prefix += nums[i];
      best = Math.max(best, prefix - suffixMin[i + 1]);
    }
    return best;
  }
}
